@push('page-scripts')
<script>
document.querySelectorAll('.branding-file').forEach(input=>input.addEventListener('change',()=>{const file=input.files?.[0];if(!file)return;const name=document.querySelector(`[data-file-name="${input.id}"]`);if(name)name.textContent=file.name;if(!file.type.startsWith('image/'))return;const preview=document.getElementById(input.dataset.preview);const url=URL.createObjectURL(file);preview.src=url;preview.onload=()=>URL.revokeObjectURL(url)}));
</script>
@endpush
